    def palindromic_string(self):
        """
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, str.
        """
        n = len(self.input_string)
        if n == 0:
            return ""
    
        # preprocess the string to add padding
        input_string = "^#" + "#".join(self.input_string) + "#$"
        p = [0] * len(input_string)
        c = r = 0
    
        for i in range(1, len(input_string) - 1):
            mirror = 2 * c - i
            if r > i:
                p[i] = min(r - i, p[mirror])
    
            while input_string[i + 1 + p[i]] == input_string[i - 1 - p[i]]:
                p[i] += 1
    
            if i + p[i] > r:
                c, r = i, i + p[i]
    
        # find the maximum palindromic substring
        max_len = 0
        center = 0
        for i in range(1, len(input_string) - 1):
            if p[i] > max_len:
                max_len = p[i]
                center = i
    
        # extract the longest palindromic substring
        start = (center - max_len) // 2
        end = start + max_len
        return self.input_string[start:end]

